window.docContents[245].resolve({"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Small-Step-Slang":{"contents":"\n\nSmall-step semantics for the richer Slang arithmetic and boolean\nexpressions.  Notations: ⟶a (arithmetic) and ⟶b (boolean).\n\nWe work in the Slang namespace, reusing the arithmetic and boolean expression\nsyntax (Aexp, Bexp) and the big-step evaluator (Aexp.eval) from the\nSlang chapter:\n\nnamespace Slang\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Smallstep: Small-step Operational Semantics","header":"3.5. Small-Step Slang","id":"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Small-Step-Slang"},"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Core-Definitions":{"contents":"\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Formal Definitions","header":"8.2.1. Core Definitions","id":"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Core-Definitions"}});